            <section class="qms-audit-browser" x-show="currentView === 'audit'"><div class="qms-category-header"><h3 x-text="archiveLeaf ? 'Authorized Evidence' : Object.keys(archivePath).length ? 'Folders' : 'Audit Plans'"></h3><small>Approved plan titles and authorized assignments</small></div><p class="qms-scope-note" x-show="archiveNotice" x-text="archiveNotice"></p><div class="qms-folders" x-show="!loading"><template x-for="folder in archiveFolders.filter(folder=>!search || (folder.name + ' ' + (folder.reference || '')).toLowerCase().includes(search.toLowerCase()))" :key="folder._id"><button type="button" class="qms-folder" @click="navigateAudit(folder.path)"><span class="qms-folder-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M20 20H4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2Z"/></svg></span><strong x-text="folder.name"></strong><small x-show="folder.reference" x-text="folder.reference"></small><small x-text="folder.kind"></small></button></template></div><div class="qms-folders" x-show="loading && !archiveLeaf" aria-hidden="true"><template x-for="index in 3" :key="index"><div class="qms-skeleton-folder"><span class="qms-skeleton qms-skeleton-icon"></span><span class="qms-skeleton qms-skeleton-title"></span><span class="qms-skeleton qms-skeleton-line"></span></div></template></div></section>
