            <div class="qms-category-header" x-show="unitId && categories.length && currentView === 'my'"><h3>Document categories</h3><small>System folders are protected; organize records in authorized subfolders.</small></div>
            <div class="qms-folders qms-categories" x-show="unitId && currentView === 'my'"><template x-for="folder in categories" :key="folder._id"><div class="qms-category-card"><button type="button" class="qms-folder" @click="navigate(collegeId, unitId, folder._id)"><span class="qms-folder-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M20 20H4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2Z"/></svg></span><strong><span x-show="!folder.userManaged" x-text="folder.code"></span> <span x-text="folder.name"></span></strong><small x-text="`${folder.counts[unitId] || 0} authorized records`"></small></button><button type="button" class="qms-configure" x-show="tree.canConfigureCategories && !folder.userManaged" @click="configureCategory(folder)" :aria-label="`Rename ${folder.name}`">Rename</button><details class="qms-folder-actions" x-show="folder.userManaged &amp;&amp; (folderPermission(folder,'rename') || folderPermission(folder,'move') || folderPermission(folder,'delete'))" @click.outside="$el.open=false"><summary :aria-label="'Actions for folder ' + folder.name">&hellip;</summary><div class="qms-action-popover"><button type="button" x-show="folderPermission(folder,'rename')" @click="$el.closest('details').open=false;openFolderDialog('rename',folder)">Rename folder</button><button type="button" x-show="folderPermission(folder,'move')" @click="$el.closest('details').open=false;openFolderDialog('move',folder)">Move folder</button><button type="button" x-show="folderPermission(folder,'delete')" @click="$el.closest('details').open=false;deleteFolder(folder)">Delete empty folder</button></div></details><span class="qms-folder-origin" x-text="folder.userManaged ? 'User subfolder' : 'System folder'"></span></div></template></div>
