            <x-qms-loading-skeleton x-show="loading && tree.canViewDocuments !== false && (currentView !== 'audit' || archiveLeaf)" x-cloak />
            <div class="qms-list-head" x-show="layout === 'list' && !loading && documents.length && tree.canViewDocuments !== false" aria-hidden="true"><span>Name</span><span>Owner</span><span>Modified</span><span>Type</span><span></span></div>
            <div class="qms-documents" :class="{'is-list': layout === 'list'}" x-ref="fileBrowser" @keydown="moveSelection($event)" x-show="!loading && tree.canViewDocuments !== false"><template x-for="document in documents" :key="document._id"><article class="qms-document" :class="{'is-selected': selectedId === document._id}" tabindex="0" :aria-label="document.title" @click="selectedId = document._id" @focus="selectedId = document._id" @dblclick="inspect(document)" @keydown.enter.self.prevent="inspect(document)" @keydown.space.self.prevent="selectedId = document._id">
                <div class="qms-file-name"><span class="qms-file-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h5"/></svg></span><div><h4 x-text="document.title"></h4><p class="qms-doc-reference" x-text="document.documentCode || document.fileCode"></p></div><span class="qms-star-mark" x-show="document.isStarred" aria-label="Starred">★</span></div>
