                <div class="qms-file-date"><span class="qms-mobile-label">Modified</span><span x-text="date(document.updatedAt || document.createdAt)"></span><small x-text="'Version ' + document.versionNumber"></small></div>
                <span class="qms-type" x-text="fileType(document)"></span>
                <div class="qms-file-menu" @click.outside="if (actionId === document._id) actionId = ''"><button type="button" class="qms-menu-trigger" :aria-label="'Actions for ' + document.title" :aria-expanded="actionId === document._id" @click.stop="actionId = actionId === document._id ? '' : document._id"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><circle cx="5" cy="12" r="1.75"/><circle cx="12" cy="12" r="1.75"/><circle cx="19" cy="12" r="1.75"/></svg></button><div class="qms-action-popover" x-show="actionId === document._id" x-cloak><button type="button" x-show="document.canOpenEditor" @click="openInEditor(document); actionId = ''">Open</button><button type="button" x-show="document.canEdit" @click="openInEditor(document, 'edit'); actionId = ''">Edit with ONLYOFFICE</button><button type="button" @click="inspect(document); actionId = ''">View Details</button><a x-show="document.canDownload" :href="documentUrl(document)" :data-file-name="document.originalName" data-evidence-preview @click="actionId = ''">Preview</a><button type="button" @click="toggleStar(document); actionId = ''" x-text="document.isStarred ? 'Remove star' : 'Add star'"></button><button type="button" x-show="document.canManage" @click="create(document); actionId = ''">Upload new version</button></div></div>
                <div class="qms-doc-actions"><button type="button" class="qms-button" x-show="document.canOpenEditor" @click="openInEditor(document)">Open</button><button type="button" class="qms-button" x-show="document.canEdit" @click="openInEditor(document, 'edit')">Edit with ONLYOFFICE</button><button type="button" class="qms-button" @click="inspect(document)">Details &amp; history</button><a x-show="document.canDownload" class="qms-button qms-gold" :href="documentUrl(document)" :data-file-name="document.originalName" data-evidence-preview>Preview</a></div>
            </article></template></div>
            <div class="qms-access-note"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 8 4v5c0 5-8 9-8 9s-8-4-8-9V7Z"/><path d="m8 12 3 3 5-6"/></svg><div><strong>Your access is role-based</strong><p>Only authorized records are shown. Audit evidence is shared for a specific assignment.</p></div></div>
