    <dialog class="qms-dialog qms-folder-dialog" x-ref="folderDialog" aria-labelledby="qms-folder-title" @cancel="if(folderSaving) $event.preventDefault()"><form @submit.prevent="saveFolder"><header><h2 id="qms-folder-title" x-text="folderMode === 'create' ? 'New Folder' : folderMode === 'rename' ? 'Rename folder' : 'Move folder'"></h2><button type="button" class="qms-close" :disabled="folderSaving" @click="$refs.folderDialog.close()" aria-label="Close folder dialog">&times;</button></header><div class="qms-dialog-body"><p class="qms-alert" role="alert" x-show="folderError" x-text="folderError"></p><p class="qms-folder-location">Current folder<strong x-text="breadcrumbs.slice(1).map(crumb=>crumb.name).join(' / ')"></strong></p><label x-show="folderMode !== 'move'">Folder name<input x-ref="folderName" x-model="folderName" :required="folderMode !== 'move'" maxlength="100" autocomplete="off" placeholder="e.g. AY 2026-2027"></label><label x-show="folderMode === 'move'">Destination folder<select x-ref="folderParent" x-model="folderParentId"><option value="" x-show="unit?.folderPermissions?.create">Department / office root</option><template x-for="folder in moveParents" :key="folder._id"><option :value="folder._id" x-text="folder.name"></option></template></select></label><p class="qms-scope-note">Ownership and classification are inherited from the parent folder.</p></div><footer><button type="button" class="qms-button" :disabled="folderSaving" @click="$refs.folderDialog.close()">Cancel</button><button type="submit" class="qms-button qms-gold" :disabled="folderSaving" x-text="folderSaving ? 'Saving...'  : folderMode === 'create' ? 'Create folder' : 'Save changes'"></button></footer></form></dialog>
    <dialog class="qms-dialog" x-ref="details" aria-labelledby="qms-detail-title"><template x-if="detail"><div><header><div><p class="qms-eyebrow">Document details</p><h2 id="qms-detail-title" x-text="detail.title"></h2></div><button type="button" class="qms-close" @click="$refs.details.close()" aria-label="Close document details">×</button></header><div class="qms-dialog-body"><p x-page-notice class="qms-alert" role="alert" x-show="error" x-text="error"></p><p x-page-notice class="qms-notice" role="status" x-show="notice" x-text="notice"></p><div class="qms-detail-grid"><section><h3>Record information</h3><dl class="qms-metadata"><dt>File code</dt><dd x-text="detail.fileCode"></dd><dt>Presentation</dt><dd x-text="type(detail.recordType)"></dd><dt>Department / office</dt><dd x-text="detail.departmentName"></dd><dt>Owner</dt><dd x-text="detail.uploadedBy"></dd><dt>Version</dt><dd x-text="detail.versionNumber"></dd><dt x-show="detail.documentCode">Document code</dt><dd x-show="detail.documentCode" x-text="detail.documentCode"></dd><dt x-show="detail.revisionLabel">Revision</dt><dd x-show="detail.revisionLabel" x-text="detail.revisionLabel"></dd><dt x-show="detail.effectiveDate">Effective date</dt><dd x-show="detail.effectiveDate" x-text="detail.effectiveDate"></dd><dt>Visibility</dt><dd x-text="label(detail.visibility || 'owner')"></dd></dl><p x-text="detail.description"></p><template x-if="detail.documentReference"><div class="qms-reference"><strong>Document reference</strong><p x-text="detail.documentReference"></p></div></template><template x-if="detail.recordType === 'physical-original'"><div class="qms-reference"><strong>Physical original · handwritten signature required</strong><p x-text="detail.physicalLocation"></p><p x-text="`Signature verification: ${label(detail.signatureStatus || 'not_verified')}`"></p><small>The authorized reviewer verifies the original through the existing evidence workflow.</small></div></template><div class="qms-actions"><a x-show="detail.canDownload" class="qms-button qms-gold" :href="documentUrl(detail)" :data-file-name="detail.originalName" data-evidence-preview>Preview file</a><a x-show="detail.canDownload" class="qms-button" :href="documentUrl(detail)">Download</a><button type="button" class="qms-button qms-gold" x-show="canEditDocument()" @click="editDocument()">Edit with ONLYOFFICE</button><button type="button" class="qms-button" x-show="detail.canManage" @click="create(detail)">Upload revised version</button></div>
            <section class="qms-permissions" x-show="detail.canManage"><h3>Document access</h3><form @submit.prevent="permissions"><label>Visibility<select x-model="detail.visibility"><option value="owner">Owner and explicitly permitted accounts</option><option value="department">Authorized department accounts</option><option value="college">Authorized college positions and department accounts</option><option value="restricted">Restricted · owner and explicitly permitted accounts</option></select></label><fieldset><legend>Explicitly permitted accounts</legend><template x-for="account in accessOptions.accounts" :key="account._id"><label class="qms-checkbox"><input type="checkbox" :value="account._id" x-model="detail.accessUserIds"><span x-text="account.name"></span></label></template><small>Organizational scope is still required.</small></fieldset><label class="qms-checkbox"><input type="checkbox" x-model="detail.downloadAllowed">Allow authorized file preview and download</label><button type="submit" class="qms-button" :disabled="saving">Save permissions</button></form><form class="qms-share" @submit.prevent="share()"><label>Share with an assigned audit<select x-model="auditId" required><option value="">Select an assigned audit</option><template x-for="audit in accessOptions.audits" :key="audit._id"><option :value="audit._id" x-text="audit.reference"></option></template></select></label><button type="submit" class="qms-button" :disabled="saving">Share evidence</button><small>Only the assigned auditor receives access. A new version needs a new share.</small></form><template x-for="id in detail.sharedAuditIds || []" :key="id"><div class="qms-share-row"><span x-text="accessOptions.audits.find(audit => audit._id === id)?.reference || 'Previously assigned audit'"></span><button type="button" class="qms-link" @click="share(id)" :disabled="saving">Revoke share</button></div></template></section></section>
            <section><h3>Version history</h3><button type="button" class="qms-button qms-gold" x-show="comparableVersions.length > 1" @click="compareVersions()">Compare versions</button><p x-show="versions.length > 1 && comparableVersions.length < 2">Comparison requires access to at least two digital versions.</p><ol class="qms-history"><template x-for="version in versions" :key="version._id"><li><button type="button" class="qms-link" @click="inspect(version, false)" x-text="`Version ${version.versionNumber} · ${version.title}`"></button><small x-text="date(version.createdAt)"></small></li></template></ol><h3>Access &amp; activity history</h3><ol class="qms-history"><template x-for="(entry, index) in activity" :key="index"><li><strong x-text="entry.action"></strong><small x-text="`${entry.actor || 'Authorized account'} · ${date(entry.at)}`"></small></li></template></ol><p x-show="!activity.length">No activity has been recorded yet.</p></section></div></div></div></template></dialog>
    <dialog class="qms-dialog qms-upload" x-ref="upload" aria-labelledby="qms-upload-title"><form x-ref="uploadForm" @submit.prevent="save"><header><div><p class="qms-eyebrow">Authorized archive record</p><h2 id="qms-upload-title" x-text="previous ? 'Add document version' : 'Add archive record'"></h2></div><button type="button" class="qms-close" @click="$refs.upload.close()" aria-label="Close add record">×</button></header><div class="qms-dialog-body"><p x-page-notice class="qms-alert" role="alert" x-show="error" x-text="error"></p><div class="qms-form-grid"><label>Department / office<select x-model="form.unitId" @change="form.categoryId=''" :disabled="!!previous" required><option value="">Select folder</option><template x-for="unit in tree.units.filter(unit => unit.canCreate || unit.folderPermissions?.upload)" :key="unit._id"><option :value="unit._id" x-text="unit.name"></option></template></select></label><label>Category<select x-model="form.categoryId" required><option value="">Select category</option><template x-for="category in formCategories" :key="category._id"><option :value="category._id" x-text="`${category.code} ${category.name}`"></option></template></select></label><label class="qms-full">Document title<input x-model="form.title" required maxlength="255"></label><label>Presentation method<select x-model="form.recordType" :disabled="!!previous"><option value="file">Authorized digital file</option><option value="digital-reference">Digital document reference</option><option value="physical-original">Physical original requiring signature</option></select></label><label>Visibility<select x-model="form.visibility" :disabled="!!previous"><option value="owner">Owner and explicit permissions</option><option value="department">Authorized department accounts</option><option value="college">Authorized college and department accounts</option><option value="restricted">Restricted</option></select></label><label class="qms-full">Description<textarea x-model="form.description" rows="2" maxlength="3000"></textarea></label><label class="qms-full" x-show="form.recordType === 'file'">Digital file<input x-ref="file" type="file" accept=".pdf,.docx,.xlsx,.pptx,.png,.jpg,.jpeg" :required="form.recordType === 'file'"><small>PDF, Word, Excel, PowerPoint, PNG, or JPEG · maximum 20 MB · encrypted at rest</small></label><label class="qms-full" x-show="form.recordType === 'digital-reference'">Document reference<input x-model="form.documentReference" :required="form.recordType === 'digital-reference'" maxlength="500" placeholder="Controlled document code or authorized location"></label><label class="qms-full" x-show="form.recordType === 'physical-original'">Location of signed original<input x-model="form.physicalLocation" :required="form.recordType === 'physical-original'" maxlength="500" placeholder="Office, cabinet, register, and document reference"><small>No scan is required. Signature verification remains pending authorized review.</small></label><label class="qms-full qms-checkbox" x-show="form.recordType === 'file'"><input type="checkbox" x-model="form.copyAuthorized" :required="form.recordType === 'file'">I am authorized to upload a digital copy of this document.</label><label class="qms-full qms-checkbox" x-show="form.recordType === 'file'"><input type="checkbox" x-model="form.downloadAllowed" :disabled="!!previous">Allow preview and download for authorized accounts</label></div><p x-show="previous" class="qms-scope-note">Existing permissions are inherited. Earlier versions and their audit links remain unchanged.</p></div><div class="qms-upload-progress" x-show="saving" role="status"><progress max="100" :value="uploadProgress"></progress><span x-text="uploadProgress &lt; 100 ? 'Uploading ' + uploadProgress + '%' : 'Securing and saving record…'"></span></div><footer><button type="button" class="qms-button" :disabled="saving" @click="$refs.upload.close()">Cancel</button><button type="submit" class="qms-button qms-gold" :disabled="saving" x-text="saving ? 'Saving…' : 'Save record'"></button></footer></form></dialog>
    <dialog class="qms-dialog qms-upload" x-ref="organization" aria-labelledby="qms-organization-title"><form @submit.prevent="assign"><header><h2 id="qms-organization-title">Positions</h2><button type="button" class="qms-close" @click="$refs.organization.close()" aria-label="Close positions">×</button></header><div class="qms-dialog-body"><p x-page-notice class="qms-alert" role="alert" x-show="error" x-text="error"></p><template x-if="organization"><div class="qms-form-grid"><label class="qms-full">Account<select x-model="selectedUser" @change="selectUser" required><option value="">Select account</option><template x-for="user in organization.users.filter(user => Number(user.roleId) !== 2)" :key="user._id"><option :value="user._id" x-text="`${user.name} (${user.email})`"></option></template></select></label><label class="qms-full">Position<select x-model="responsibility"><template x-for="role in organization.responsibilities" :key="role"><option :value="role" x-text="label(role)"></option></template></select></label><label class="qms-full" x-show="responsibility === 'cluster_administrator'">Cluster<select x-model="cluster" :required="responsibility === 'cluster_administrator'"><option value="">Choose a cluster</option><template x-for="(name, id) in organization.clusters || {}" :key="id"><option :value="id" x-text="name"></option></template></select></label><fieldset class="qms-full" x-show="['college_dean', 'college_secretary'].includes(responsibility)"><legend>Explicitly authorized colleges</legend><template x-for="college in tree.colleges" :key="college._id"><label class="qms-checkbox"><input type="checkbox" :value="college._id" x-model="scopeColleges"><span x-text="college.name"></span></label></template></fieldset><fieldset class="qms-full" x-show="!['college_dean', 'college_secretary', 'cluster_administrator'].includes(responsibility)"><legend>Explicitly authorized departments / offices</legend><template x-for="unit in tree.units" :key="unit._id"><label class="qms-checkbox"><input type="checkbox" :value="unit._id" x-model="scopeUnits"><span x-text="unit.name"></span></label></template></fieldset><p class="qms-full qms-scope-note">The account's existing department remains its home assignment. Authentication roles are unchanged. Auditors receive evidence only through authorized audit sharing.</p></div></template></div><footer><button type="button" class="qms-button" @click="$refs.organization.close()">Cancel</button><button type="submit" class="qms-button qms-gold" :disabled="saving || !selectedUser">Save position</button></footer></form></dialog>
    <dialog class="qms-dialog qms-document-editor" x-ref="editor" aria-labelledby="qms-editor-title" @close="closeEditor()">
        <header><div><p class="qms-eyebrow">QMS Documents · ONLYOFFICE</p><h2 id="qms-editor-title" x-text="editorTitle"></h2><p class="qms-editor-location" x-text="editorLocation"></p><span class="qms-editor-saved" x-show="editorSavedCount > 0 &amp;&amp; editorMessage.startsWith('Version ')">Saved</span></div><button type="button" class="qms-button" data-editor-back @click="$refs.editor.close()" aria-label="Back to QMS Documents">Back to QMS Documents</button></header><div class="qms-editor-toolbar"><button type="button" class="qms-button qms-gold" data-editor-save x-show="editorMode === 'edit'" :disabled="editorSaving || !editorSession" @click="saveEditor()" x-text="editorSaving ? 'Requesting save…' : 'Save'">Save</button><span class="qms-editor-mode" x-text="editorMode === 'edit' ? 'Edit Document' : 'Read-only Preview'"></span><a class="qms-button" x-show="detail?.canDownload" :href="detail ? documentUrl(detail) : '#'" :data-file-name="detail?.originalName" data-evidence-preview>Preview</a><button type="button" class="qms-button" @click="$refs.editor.close(); $refs.details.showModal()">Versions &amp; Details</button><p role="status" aria-live="polite" x-text="editorMessage"></p></div>
        <div class="qms-editor-body" x-ref="editorBody"></div>
    </dialog>
    <dialog class="qms-dialog qms-comparison" x-ref="comparison" aria-labelledby="qms-comparison-title" @close="clearComparison()">
        <header><div><p class="qms-eyebrow">Document history</p><h2 id="qms-comparison-title">Compare versions</h2><p>View earlier and revised files side by side.</p></div><button type="button" class="qms-close" @click="$refs.comparison.close()" aria-label="Close version comparison">&times;</button></header>
        <div class="qms-comparison-grid">
            <section><label>Earlier version<select x-model="comparisonIds[0]" @change="loadComparison(0)"><template x-for="version in comparisonVersions" :key="version._id"><option :value="version._id" x-text="`Version ${version.versionNumber} · ${version.title}`"></option></template></select></label><div class="qms-comparison-pane" x-ref="compareLeft"></div></section>
            <section><label>Revised version<select x-model="comparisonIds[1]" @change="loadComparison(1)"><template x-for="version in comparisonVersions" :key="version._id"><option :value="version._id" x-text="`Version ${version.versionNumber} · ${version.title}`"></option></template></select></label><div class="qms-comparison-pane" x-ref="compareRight"></div></section>
        </div>
        <footer><button type="button" class="qms-button" @click="$refs.comparison.close()">Close</button></footer>
    </dialog>
</section>
@include('auditee.evidence-preview-modal', ['closeLabel' => 'Close preview'])
